public static int squarePermutations(int[] A) {
    int n = A.length;
    // count frequencies
    Map<Integer,Integer> freq = new HashMap<>();
    for (int v:A) freq.put(v, freq.getOrDefault(v, 0)+1);
    int[] nums = freq.keySet().stream().mapToInt(i->i).toArray();
    // recursively build permutations
    // we need total count
    int[] count = new int[1];
    // start with each number as start
    for (int num:nums) {
        freq.put(num, freq.get(num)-1);
        if (freq.get(num)==0) freq.remove(num);
        backtrack(num, freq, n-1, count);
        // restore
        freq.put(num, freq.getOrDefault(num,0)+1);
    }
    return count[0];
}

